#include "string.h"
size_t strlen(const char *අනුලකුණු_වැල_දත්ත) { const char *자료위치 = අනුලකුණු_වැල_දත්ත; while (*자료위치) 자료위치++; return 자료위치 - අනුලකුණු_වැල_දත්ත; }
int memcmp(const void *첫째값, const void *둘째값, size_t 개수) { const unsigned char *x_ඛණ්ඩාංකය = 첫째값, *세로좌표 = 둘째값; while (개수--) { if (*x_ඛණ්ඩාංකය != *세로좌표) return (int)*x_ඛණ්ඩාංකය - *세로좌표; x_ඛණ්ඩාංකය++; 세로좌표++; } return 0; }
void *memmove(void *ගමනාන්තය_දත්ත, const void *අනුලකුණු_වැල_දත්ත, size_t 개수) { unsigned char *x_ඛණ්ඩාංකය = ගමනාන්තය_දත්ත; const unsigned char *세로좌표 = අනුලකුණු_වැල_දත්ත; if (x_ඛණ්ඩාංකය < 세로좌표) { for (size_t 순번 = 0; 순번 < 개수; 순번++) x_ඛණ්ඩාංකය[순번] = 세로좌표[순번]; } else { while (개수) { 개수--; x_ඛණ්ඩාංකය[개수] = 세로좌표[개수]; } } return ගමනාන්තය_දත්ත; }
int strncmp(const char *첫째값, const char *둘째값, size_t 개수) { while (개수--) { unsigned char x_ඛණ්ඩාංකය = *첫째값++, 세로좌표 = *둘째값++; if (x_ඛණ්ඩාංකය != 세로좌표) return (int)x_ඛණ්ඩාංකය-세로좌표; if (!x_ඛණ්ඩාංකය) return 0; } return 0; }
/* lwIP only uses this for small decimal interface numbers. */
long strtol(const char *අනුලකුණු_වැල_දත්ත, char **නිමා_කරන්න_ඕෆ්සෙට්, int පසුබිම_අගය) {
    const char *ඇරඹුම_ඕෆ්සෙට් = අනුලකුණු_වැල_දත්ත; unsigned long අගය = 0; int සංකේතනය_අගය = 1, 하나라도 = 0;
    while (*අනුලකුණු_වැල_දත්ත == ' ' || (*අනුලකුණු_වැල_දත්ත >= 9 && *අනුලකුණු_වැල_දත්ත <= 13)) අනුලකුණු_වැල_දත්ත++;
    if (*අනුලකුණු_වැල_දත්ත == '-' || *අනුලකුණු_වැල_දත්ත == '+') { if (*අනුලකුණු_වැල_දත්ත == '-') සංකේතනය_අගය = -1; අනුලකුණු_වැල_දත්ත++; }
    if (පසුබිම_අගය == 0) පසුබිම_අගය = 10;
    while (*අනුලකුණු_වැල_දත්ත >= '0' && *අනුලකුණු_වැල_දත්ත <= '9' && *අනුලකුණු_වැල_දත්ත - '0' < පසුබිම_අගය) {
        unsigned සංඛ්_යාංකය_අගය = *අනුලකුණු_වැල_දත්ත++ - '0'; 하나라도 = 1;
        if (අගය > (0x7ffffffffffffffful - සංඛ්_යාංකය_අගය) / (unsigned)පසුබිම_අගය) අගය = 0x7ffffffffffffffful;
        else අගය = අගය * පසුබිම_අගය + සංඛ්_යාංකය_අගය;
    }
    if (නිමා_කරන්න_ඕෆ්සෙට්) *නිමා_කරන්න_ඕෆ්සෙට් = (char *)(하나라도 ? අනුලකුණු_වැල_දත්ත : ඇරඹුම_ඕෆ්සෙට්); return සංකේතනය_අගය > 0 ? (long)අගය : -(long)අගය;
}
int atoi(const char *අනුලකුණු_වැල_දත්ත) { return (int)strtol(අනුලකුණු_වැල_දත්ත, 0, 10); }
